// =====================================================================
// WF5 - Validar los parámetros de la consulta
// Parámetros opcionales en la URL:
//   ?codigo=TCK-000001  -> un ticket específico
//   ?limite=50          -> cuántos tickets devolver (1 a 200)
// Seguridad: solo se aceptan estos dos parámetros, con formato estricto;
// cualquier otro se ignora. Nunca se arma SQL con el texto recibido.
// =====================================================================
const q = $input.first().json.query || {};
const errores = [];

let codigo = '';
if (q.codigo !== undefined && q.codigo !== '') {
  const c = String(q.codigo).trim().toUpperCase();
  if (/^TCK-\d{6}$/.test(c)) {
    codigo = c;
  } else {
    errores.push('codigo debe tener el formato TCK-000000');
  }
}

let limite = 50;
if (q.limite !== undefined && q.limite !== '') {
  const n = Number(q.limite);
  if (Number.isInteger(n) && n >= 1 && n <= 200) {
    limite = n;
  } else {
    errores.push('limite debe ser un número entero entre 1 y 200');
  }
}

return [{ json: { valido: errores.length === 0, errores, codigo, limite } }];
